llm = LLM(
    model="azure/gpt-4o"
)

    @agent
    def manager(self) -> Agent:
        return Agent(config=self.agents_config["manager"], verbose=True, llm=llm)

    @agent
    def analysis_dept(self) -> Agent:
        return Agent(
            config=self.agents_config["analysis_dept"],
            verbose=True,
            llm=llm
        )

    @crew
    def crew(self) -> Crew:
        return Crew(
            agents=[self.analysis_dept(), self.reporting_dept()],
            tasks=[self.draft_report()],
            process=Process.hierarchical, 
            manager_agent=self.manager(), 
            verbose=True
